let {data}=$props();const {t,get}=useLocale();let search=$state(''),modal=$state(''),editing=$state(''),form=$state<Record<string,any>>({}),busy=$state(false),error=$state(''),notice=$state(''),selectedRun=$state('');
const titles:Record<string,[string,string,string,string]>={dashboard:['Dashboard','Dashboard','Selamat datang! Ini kabar terbaru dari tim AI Anda.','Welcome back! Here’s what’s happening with your AI team.'],agents:['Karyawan AI','AI Employees','Tim yang mengenal bisnis dan membantu pekerjaan Anda.','A team that understands your business and helps you get things done.'],divisions:['Divisi','Divisions','Susun tim sesuai kebutuhan bisnis Anda.','Organize your team around your business.'],tasks:['Tugas','Tasks','Dari ide menjadi hasil, bersama tim AI Anda.','Turn ideas into outcomes with your AI team.'],projects:['Proyek','Projects','Satu tempat untuk tujuan dan pekerjaan bisnis Anda.','One home for your business goals and work.'],knowledge:['Company Knowledge','Company Knowledge','Ajarkan tim AI Anda tentang bisnis, produk, dan cara kerja Anda.','Teach your AI team about your business, products, and processes.'],company:['Profil Bisnis','Business Profile','Konteks perusahaan yang menjadi dasar kerja seluruh tim.','The company context that guides your entire team.'],rooms:['Rooms','Rooms','Ikuti percakapan kerja dan hasil kolaborasi tim Anda.','Follow your team’s working conversations and collaborative results.'],approvals:['Persetujuan','Approvals','Tinjau pekerjaan yang memerlukan keputusan Anda.','Review work that needs your decision.'],'virtual-office':['Virtual Office','Virtual Office','Satu pandangan untuk seluruh divisi dan karyawan AI Anda.','A shared view of your divisions and AI employees.'],activity:['Aktivitas','Activity','Riwayat pekerjaan dan perubahan di workspace Anda.','A history of work and changes in your workspace.'],providers:['AI Provider','AI Provider','Hubungkan model AI untuk mengaktifkan karyawan Anda.','Connect an AI model to activate your employees.'],usage:['Penggunaan AI','AI Usage','Pantau penggunaan model dari pekerjaan yang benar-benar dijalankan.','Track model usage from actual work.'],settings:['Pengaturan','Settings','Kelola bahasa bisnis dan kendali operasional tim Anda.','Manage your business language and team operations.']};
let section=$derived(data.section);let title=$derived(titles[section]??titles.dashboard);let agents=$derived(data.entities.filter(e=>e.kind==='agent'));let tasks=$derived(data.entities.filter(e=>e.kind==='task'));let projects=$derived(data.entities.filter(e=>e.kind==='project'));let divisions=$derived(data.entities.filter(e=>e.kind==='division'));let knowledge=$derived(data.entities.filter(e=>e.kind==='knowledge'));let running=$derived(data.runs.filter(r=>['queued','running'].includes(r.status)));let completed=$derived(tasks.filter(e=>e.data.status==='completed').length);let pending=$derived(data.approvals.filter(a=>a.status==='pending'));let kind=$derived(({agents:'agent',divisions:'division',projects:'project',tasks:'task',knowledge:'knowledge'} as Record<string,string>)[section]);let filtered=$derived(data.entities.filter(e=>e.kind===kind&&`${e.data.name} ${e.data.description??''} ${e.data.role??''}`.toLowerCase().includes(search.toLowerCase())));let run=$derived(data.runs.find(r=>r.id===selectedRun)??data.runs[0]);let messages=$derived(run?data.events.filter(e=>e.run_id===run.id).toReversed():[]);let canAdmin=$derived(['owner','admin'].includes(data.role));let totalTokens=$derived(data.runs.reduce((n,r)=>n+r.input_tokens+r.output_tokens,0));
function entityName(id:string|undefined){return data.entities.find(e=>e.id===id)?.data.name??'—';}
function date(value:string){return new Date(value).toLocaleDateString(get()==='id'?'id-ID':'en-US',{day:'numeric',month:'short'});}
function statusLabel(status:string){const labels:Record<string,[string,string]>={todo:['Belum dimulai','To do'],in_progress:['Dikerjakan','In progress'],completed:['Selesai','Completed'],active:['Aktif','Active'],paused:['Dijeda','Paused'],queued:['Antrean','Queued'],running:['Bekerja','Working'],waiting_approval:['Menunggu keputusan','Awaiting approval'],succeeded:['Berhasil','Succeeded'],failed:['Gagal','Failed'],cancelled:['Dibatalkan','Cancelled'],planning:['Perencanaan','Planning'],published:['Diterbitkan','Published'],draft:['Draft','Draft'],pending:['Menunggu','Pending'],approved:['Disetujui','Approved'],rejected:['Ditolak','Rejected'],expired:['Kedaluwarsa','Expired']};return labels[status]?t(...labels[status]):status;}
function dialogMount(node:HTMLDialogElement){node.showModal();}
function open(type:string,entity?:any){error='';editing=entity?.id??'';form=entity?{...entity.data}:{name:'',description:'',instructions:'',content:'',role:'',color:'blue',avatar:'blue',status:type==='knowledge'?'published':type==='task'?'todo':'active',priority:'medium',category:'company',divisionId:null,agentId:null,projectId:null,requiresApproval:false,schedule:'none'};if(type==='profile')form={...data.workspace.profile,name:data.workspace.name};if(type==='provider')form={model:data.provider?.model??'',apiKey:''};modal=type;}
async function action(fn:()=>Promise<unknown>,message?:string){busy=true;error='';notice='';try{await fn();await invalidate('app:data');if(message)notice=message;return true;}catch(e){error=(e as Error).message;return false;}finally{busy=false;}}
async function save(e:SubmitEvent){e.preventDefault();const ok=await action(()=>post(`workspaces/${data.workspace.id}/${modal==='profile'?'profile':modal==='provider'?'provider':`entities${editing?'/'+editing:''}`}`,modal==='profile'||modal==='provider'?form:{kind:modal,data:form}),t('Perubahan tersimpan.','Changes saved.'));if(ok)modal='';}
async function remove(entity:any){if(!confirm(t(`Hapus “${entity.data.name}”?`,`Delete “${entity.data.name}”?`)))return;await action(()=>post(`workspaces/${data.workspace.id}/entities/${entity.id}/delete`,{}));}
async function start(task:any){await action(async()=>{const response=await post(`workspaces/${data.workspace.id}/runs`,{taskId:task.id});selectedRun=response.id;},t('Tugas masuk antrean. Lihat progres di Rooms.','Task queued. Follow progress in Rooms.'));}
async function updateTask(task:any,status:string){await action(()=>post(`workspaces/${data.workspace.id}/entities/${task.id}`,{kind:'task',data:{...task.data,status}}));}
onMount(()=>{const timer=setInterval(()=>{if(data.runs.some(r=>['queued','running','waiting_approval'].includes(r.status)))void invalidate('app:data');},4000);return()=>clearInterval(timer);});
</script>
