 <div class="stats-grid">{#each [{icon:Bot,label:t('Karyawan AI','AI employees'),value:agents.length,note:t('Siap membantu bisnis Anda','Built around your business'),color:'blue'},{icon:ListTodo,label:t('Tugas berjalan','Active runs'),value:running.length,note:t('Antrean dan sedang dikerjakan','Queued and in progress'),color:'green'},{icon:FolderKanban,label:t('Proyek aktif','Active projects'),value:projects.filter(p=>p.data.status==='active').length,note:t('Tujuan bisnis yang dikerjakan','Business goals in motion'),color:'purple'},{icon:ShieldCheck,label:t('Butuh persetujuan','Needs approval'),value:pending.length,note:t('Keputusan ada di tangan Anda','You make the final call'),color:'orange'}] as stat}<div class="card stat-card"><span class="stat-icon {stat.color}"><stat.icon size={23}/></span><div><p>{stat.label}</p><strong>{stat.value}</strong><small>{stat.note}</small></div></div>{/each}</div>
