.data.projectId===entity.id&&t.data.status==='completed').length} / {tasks.filter(t=>t.data.projectId===entity.id).length} {t('tugas selesai','tasks completed')}</span><div class="progress-track"><i style={`width:${tasks.filter(t=>t.data.projectId===entity.id).length?tasks.filter(t=>t.data.projectId===entity.id&&t.data.status==='completed').length/tasks.filter(t=>t.data.projectId===entity.id).length*100:0}%`}></i></div></div><div class="entity-bottom"><span class="badge {entity.data.status}">{statusLabel(entity.data.status)}</span><small>{date(entity.created_at)}</small></div>{/if}</article>{:else}<div class="card empty wide"><div class="empty-icon"><Sparkles size={30}/></div><h3>{search?t('Tidak ada hasil','No results found'):t('Mulai dari sini','Start here')}</h3><p>{search?t('Coba kata pencarian lain.','Try another search term.'):t('Tambahkan informasi pertama untuk membangun workspace Anda.','Add your first item to build your workspace.')}</p>{#if !search}<button class="primary" onclick={()=>open(kind)}><Plus size={16}/>{t('Tambah sekarang','Add now')}</button>{/if}</div>{/each}</div>
