an><button class="secondary full spaced" disabled={busy||!canAdmin} onclick={()=>action(()=>post(`workspaces/${data.workspace.id}/profile`,{...data.workspace.profile,name:data.workspace.name,paused:!data.workspace.profile.paused}))}>{#if data.workspace.profile.paused}<Play size={16}/>{t('Lanjutkan operasi','Resume operations')}{:else}<Pause size={16}/>{t('Jeda operasi','Pause operations')}{/if}</button></section><section class="card padded"><h2>{t('Perusahaan lain?','Another business?')}</h2><p>{t('Pisahkan konteks, data, dan tim untuk setiap bisnis.','Keep each business’s context, data, and team separate.')}</p><a href="/onboarding" class="text-link"><Plus size={16}/>{t('Tambah perusahaan','Add company')}</a></section></div></div>
