 <div class="provider-grid"><section class="card padded provider-card"><div class="provider-symbol"><Sparkles size={32}/></div><div class="provider-title"><h2>OpenAI</h2><span class="badge {data.provider?'active':'draft'}">{data.provider?t('Tersimpan','Configured'):t('Belum terhubung','Not connected')}</span></div><p>{t('Gunakan API key milik bisnis Anda untuk menjalankan tugas dan kolaborasi agent.','Use your business API key to run tasks and agent collaboration.')}</p><div class="detail-row"><span>Model</span><strong>{data.provider?.model??'—'}</strong></div><div class="detail-row"><span>API key</span><strong>{data.provider?'••••••••••••••••':t('Belum diatur','Not configured')}</strong></div><button class="primary full" onclick={()=>open('provider')} disabled={!canAdmin}><Plug size={16}/>{data.provider?t('Ubah konfigurasi','Edit configuration'):t('Hubungkan','Connect')}</button></section><section class="card padded"><h2>{t('Bagaimana koneksi digunakan?','How is the connection used?')}</h2><div class="info-step"><span>1</span><p>{t('Tambahkan API key dan ID model yang tersedia di akun provider Anda.','Add an API key and a model ID available in your provider account.')}</p></div><div class="info-step"><span>2</span><p>{t('Beri tugas kepada karyawan AI. Worker memprosesnya dengan konteks perusahaan.','Assign a task. The worker processes it with your company context.')}</p></div><div class="info-step"><span>3</span><p>{t('Pantau hasil dan token di Rooms dan Penggunaan AI.','Follow results and tokens in Rooms and AI Usage.')}</p></div><div class="alert">{t('Key disimpan terenkripsi. Status tersimpan belum berarti credential sudah diverifikasi. Penggunaan ditagihkan oleh provider Anda.','Keys are stored encrypted. Configured does not mean credentials have been verified. Usage is billed by your provider.')}</div></section></div>
{:else if section==='rooms'}
 <div class="rooms-layout"><aside class="card room-list"><div class="card-heading"><h2>{t('Percakapan tugas','Task conversations')}</h2><span class="tag">{data.runs.length}</span></div>{#each data.runs as r}<button class:chosen={run?.id===r.id} onclick={()=>selectedRun=r.id}><span class="room-hash">#</span><div><strong>{entityName(r.task_id)}</strong><small>{statusLabel(r.status)} · {date(r.created_at)}</small></div></button>{:else}<div class="empty compact"><MessagesSquare size={30}/><p>{t('Jalankan tugas untuk membuka percakapan kerja.','Run a task to open a working conversation.')}</p><a class="text-link" href="/tasks">{t('Buka tugas','Go to tasks')}<ArrowRight size={14}/></a></div>{/each}</aside><section class="card conversation">{#if run}<div class="conversation-header"><div><h2># {entityName(run.task_id)}</h2><span class="badge {run.status}">{statusLabel(run.status)}</span></div>{#if ['queued','running','waiting_approval'].includes(run.status)}<button class="secondary" disabled={busy} onclick={()=>action(()=>post(`workspaces/${data.workspace.id}/runs/${run.id}/cancel`,{}))}><X size={15}/>{t('Batalkan','Cancel')}</button>{/if}</div><div class="messages">{#each messages as message}<div class="message"><div class="avatar small blue">{message.actor.slice(0,1)}</div><div><div class="message-meta"><strong>{message.actor}</strong><small>{date(message.created_at)} · {new Date(message.created_at).toLocaleTimeString(get()==='id'?'id-ID':'en-US',{hour:'2-digit',minute:'2-digit'})}</small></div><div class="message-content">{message.message}</div><small class="subtle">{message.kind}</small></div></div>{/each}{#if run.result}<div class="result-box"><h3><CheckCircle2 size={18}/>{t('Hasil pekerjaan','Work result')}</h3><div class="preserve">{run.result}</div></div>{/if}{#if run.error_code}<div class="alert error">{run.error_code}</div>{/if}</div><div class="conversation-footer"><ShieldCheck size={16}/>{t('Riwayat kerja agent. Instruksi baru dibuat melalui Tugas.','Agent work history. Create new instructions through Tasks.')}</div>{:else}<div class="empty"><div class="empty-icon"><MessagesSquare size={35}/></div><h3>{t('Tempat ide menjadi percakapan','Where ideas become conversations')}</h3><p>{t('Pilih pekerjaan untuk melihat progres, diskusi agent, dan hasilnya.','Choose a task run to see progress, agent discussions, and results.')}</p></div>{/if}</section></div>
{:else if section==='approvals'}
 <div class="card"><div class="card-heading"><h2>{t('Perlu keputusan Anda','Your decision is needed')}</h2><span class="badge pending">{pending.length} {t('menunggu','pending')}</span></div>{#each data.approvals as approval}{@const approvalRun=data.runs.find(r=>r.id===approval.run_id)}<div class="approval-row"><div class="stat-icon orange"><ShieldCheck size={23}/></div><div><h3>{approvalRun?entityName(approvalRun.task_id):approval.run_id}</h3><p>{t('Izinkan agent memulai pekerjaan AI dengan konteks perusahaan.','Allow the agent to begin AI work using company context.')}</p><small>{t('Berlaku hingga','Expires')} {new Date(approval.expires_at).toLocaleString(get()==='id'?'id-ID':'en-US')}</small></div>{#if approval.status==='pending'}<button class="secondary" disabled={busy||!canAdmin} onclick={()=>action(()=>post(`workspaces/${data.workspace.id}/approvals/${approval.id}`,{decision:'reject'}))}>{t('Tolak','Reject')}</button><button class="primary" disabled={busy||!canAdmin} onclick={()=>action(()=>post(`workspaces/${data.workspace.id}/approvals/${approval.id}`,{decision:'approve'}))}><Check size={15}/>{t('Setujui','Approve')}</button>{:else}<span class="badge {approval.status}">{statusLabel(approval.status)}</span>{/if}</div>{:else}<div class="empty"><div class="empty-icon green"><ShieldCheck size={30}/></div><h3>{t('Semua terkendali','All under control')}</h3><p>{t('Belum ada pekerjaan yang meminta persetujuan.','No work is awaiting your approval.')}</p></div>{/each}</div>
{:else if section==='virtual-office'}
 <div class="office-banner"><div><span class="eyebrow">YOUR DIGITAL HEADQUARTERS</span><h2>{data.workspace.name}</h2><p>{agents.length} {t('karyawan AI','AI employees')} · {divisions.length} {t('divisi','divisions')} · {running.length} {t('pekerjaan berjalan','active runs')}</p></div><a class="button secondary" href="/divisions"><Users size={16}/>{t('Kelola divisi','Manage divisions')}</a></div><div class="office-grid">{#each [...divisions,{id:'unassigned',data:{name:t('Ruang bersama','Shared space'),color:'blue'}}] as division}{@const team=agents.filter(a=>division.id==='unassigned'?!a.data.divisionId:a.data.divisionId===division.id)}<section class="card office-room"><div class="office-room-heading"><span class="stat-icon {division.data.color}"><Building2 size={21}/></span><div><h2>{division.data.name}</h2><small>{team.length} {t('karyawan','employees')}</small></div><span class="room-indicator"></span></div><div class="desks">{#each team as agent}<a class="desk" href="/agents"><div class="desk-monitor"></div><div class="avatar {agent.data.avatar}">{agent.data.name.slice(0,1)}</div><strong>{agent.data.name}</strong><small>{agent.data.status==='paused'?t('Dijeda','Paused'):t('Tersedia','Available')}</small></a>{:else}<div class="empty-desk"><Users size={26}/><span>{t('Siap untuk tim Anda','Ready for your team')}</span><a href="/agents">{t('Tambahkan karyawan','Add an employee')}<Plus size={13}/></a></div>{/each}</div></section>{/each}</div><div class="alert"><Building2 size={17}/>{t('Tampilan kantor dasar. Status eksekusi aktual dapat dilihat di Rooms.','Basic office view. Actual execution status is available in Rooms.')}</div>
{:else if section==='activity'}
 <section class="card"><div class="card-heading"><h2>{t('Riwayat workspace','Workspace history')}</h2><span class="tag">{t('100 aktivitas terbaru','Latest 100 events')}</span></div><div class="activity-list full-activity">{#each data.events as e}<div class="activity-item"><span class="event-dot"><Activity size={16}/></span><div><strong>{e.actor}<span class="tag">{e.kind}</span></strong><p>{e.message}</p><small>{new Date(e.created_at).toLocaleString(get()==='id'?'id-ID':'en-US')}</small></div>{#if e.run_id}<a href="/rooms" class="icon-btn" aria-label="Open room"><ArrowUpRight size={18}/></a>{/if}</div>{/each}</div></section>
{:else if section==='usage'}
 <div class="stats-grid three">{#each [{label:t('Total token','Total tokens'),value:totalTokens.toLocaleString(),icon:Zap,color:'blue'},{label:t('Eksekusi tercatat','Recorded runs'),value:data.runs.length,icon:Activity,color:'purple'},{label:t('Eksekusi berhasil','Successful runs'),value:data.runs.filter(r=>r.status==='succeeded').length,icon:CheckCircle2,color:'green'}] as stat}<div class="card stat-card"><span class="stat-icon {stat.color}"><stat.icon size={23}/></span><div><p>{stat.label}</p><strong>{stat.value}</strong><small>{t('100 eksekusi terbaru','Latest 100 runs')}</small></div></div>{/each}</div><div class="alert"><AlertCircle size={18}/>{t('Biaya belum dihitung. Token berasal dari respons provider; rincian tagihan tersedia di akun provider Anda.','Cost is not calculated yet. Tokens come from provider responses; billing details are available in your provider account.')}</div><section class="card"><div class="card-heading"><h2>{t('Rincian penggunaan','Usage details')}</h2></div><div class="table-wrap"><table><thead><tr><th>{t('Pekerjaan','Work')}</th><th>Status</th><th>Input tokens</th><th>Output tokens</th><th>{t('Tanggal','Date')}</th></tr></thead><tbody>{#each data.runs as r}<tr><td>{entityName(r.task_id)}</td><td><span class="badge {r.status}">{statusLabel(r.status)}</span></td><td>{r.input_tokens}</td><td>{r.output_tokens}</td><td>{date(r.created_at)}</td></tr>{:else}<tr><td colspan="5" class="empty">{t('Penggunaan akan muncul setelah tugas dijalankan.','Usage will appear after you run a task.')}</td></tr>{/each}</tbody></table></div></section>
{/if}
{#if modal}<div class="modal-backdrop" role="presentation"><dialog class="modal card" use:dialogMount onclose={()=>modal=''} aria-labelledby="modal-title"><div class="modal-heading"><div><span class="eyebrow">ORVEXA WORKSPACE</span><h2 id="modal-title">{modal==='profile'?t('Profil perusahaan','Company profile'):modal==='provider'?t('Koneksi AI provider','AI provider connection'):`${editing?t('Edit','Edit'):t('Tambah','Add')} ${t(({agent:'karyawan AI',task:'tugas',project:'proyek',division:'divisi',knowledge:'knowledge'} as any)[modal],({agent:'AI employee',task:'task',project:'project',division:'division',knowledge:'knowledge'} as any)[modal])}`}</h2></div><button class="icon-btn" onclick={()=>modal=''} aria-label="Close dialog"><X size={20}/></button></div><form onsubmit={save}>{#if error}<div class="alert error" role="alert">{error}</div>{/if}{#if modal==='provider'}<label>Model ID<input required bind:value={form.model} placeholder="Model ID from your provider" maxlength="100"/></label><label>API key<input required type="password" bind:value={form.apiKey} autocomplete="off" minlength="10" maxlength="500" placeholder="sk-…"/></label><p class="subtle">{t('Key dienkripsi dan tidak pernah dikirim kembali ke browser.','The key is encrypted and never returned to your browser.')}</p>{:else}<label>{t('Nama','Name')}<input required minlength="2" maxlength="120" bind:value={form.name}/></label>{#if modal==='agent'}<label>{t('Jabatan / peran','Job title / role')}<input required minlength="2" maxlength="120" bind:value={form.role} placeholder="Marketing Specialist"/></label><label>{t('Divisi','Division')}<select bind:value={form.divisionId}><option value={null}>{t('Lintas divisi','Cross-functional')}</option>{#each divisions as d}<option value={d.id}>{d.data.name}</option>{/each}</select></label><label>{t('Panduan kerja','Working instructions')}<textarea rows="5" maxlength="8000" bind:value={form.instructions} placeholder={t('Tanggung jawab, cara kerja, dan hasil yang diharapkan…','Responsibilities, approach, and expected outcomes…')}></textarea></label><div class="form-row"><label>Status<select bind:value={form.status}><option value="active">{t('Aktif','Active')}</option><option value="paused">{t('Dijeda','Paused')}</option></select></label><label>{t('Warna avatar','Avatar color')}<select bind:value={form.avatar}><option value="blue">Blue</option><option value="purple">Purple</option><option value="green">Green</option><option value="orange">Orange</option></select></label></div>{:else if modal==='knowledge'}<div class="form-row"><label>{t('Kategori','Category')}<select bind:value={form.category}><option value="company">{t('Perusahaan','Company')}</option><option value="product">{t('Produk / jasa','Products / services')}</option><option value="policy">{t('Kebijakan','Policy')}</option><option value="faq">FAQ</option></select></label><label>Status<select bind:value={form.status}><option value="published">{t('Diterbitkan','Published')}</option><option value="draft">Draft</option></select></label></div><label>{t('Isi knowledge','Knowledge content')}<textarea required minlength="5" maxlength="20000" rows="9" bind:value={form.content} placeholder={t('Tuliskan informasi bisnis yang boleh digunakan tim AI…','Write the business information your AI team can use…')}></textarea></label>{:else}<label>{t('Deskripsi','Description')}<textarea rows="4" maxlength={modal==='profile'?6000:4000} bind:value={form.description}></textarea></label>{#if modal==='profile'}<label>{t('Bidang usaha','Industry')}<input maxlength="120" bind:value={form.industry}/></label><label>Website<input type="url" bind:value={form.website} placeholder="https://…"/></label><div class="form-row"><label>{t('Bahasa kerja','Working language')}<select bind:value={form.language}><option value="id">Bahasa Indonesia</option><option value="en">English</option></select></label><label>Timezone<input required bind:value={form.timezone}/></label></div>{:else if modal==='task'}<div class="form-row"><label>{t('Karyawan AI','AI employee')}<select bind:value={form.agentId}><option value={null}>{t('Belum ditugaskan','Unassigned')}</option>{#each agents as a}<option value={a.id}>{a.data.name} · {a.data.role}</option>{/each}</select></label><label>{t('Proyek','Project')}<select bind:value={form.projectId}><option value={null}>{t('Tanpa proyek','No project')}</option>{#each projects as p}<option value={p.id}>{p.data.name}</option>{/each}</select></label></div><div class="form-row"><label>Status<select bind:value={form.status}><option value="todo">{t('Belum dimulai','To do')}</option><option value="in_progress">{t('Dikerjakan','In progress')}</option><option value="completed">{t('Selesai','Completed')}</option></select></label><label>{t('Prioritas','Priority')}<select bind:value={form.priority}><option value="low">{t('Rendah','Low')}</option><option value="medium">{t('Sedang','Medium')}</option><option value="high">{t('Tinggi','High')}</option></select></label></div><label>{t('Jadwal otomatis','Automatic schedule')}<select bind:value={form.schedule}><option value="none">{t('Manual','Manual')}</option><option value="daily">{t('Setiap 24 jam','Every 24 hours')}</option><option value="weekly">{t('Setiap 7 hari','Every 7 days')}</option></select><small>{t('Jadwal pertama dimulai setelah interval tersebut. Memerlukan provider aktif.','The first scheduled run starts after this interval. Requires a configured provider.')}</small></label><label class="checkbox-row"><input type="checkbox" bind:checked={form.requiresApproval}/><span>{t('Minta persetujuan sebelum agent mulai bekerja','Require approval before AI work begins')}</span></label>{:else if modal==='project'}<label>Status<select bind:value={form.status}><option value="planning">{t('Perencanaan','Planning')}</option><option value="active">{t('Aktif','Active')}</option><option value="completed">{t('Selesai','Completed')}</option></select></label>{:else if modal==='division'}<label>{t('Warna divisi','Division color')}<select bind:value={form.color}><option value="blue">Blue</option><option value="purple">Purple</option><option value="green">Green</option><option value="orange">Orange</option></select></label>{/if}{/if}{/if}<div class="modal-footer"><button class="secondary" type="button" onclick={()=>modal=''}>{t('Batal','Cancel')}</button><button class="primary" disabled={busy}><Check size={16}/>{busy?t('Menyimpan…','Saving…'):t('Simpan','Save')}</button></div></form></dialog></div>{/if}
